--region helper
function ActivityDirectDrawMemberDialog:ClearThreads()
    local count = table.count(self._threadPool)
    for i = 1, count do
        cs_coroutine.stop(self._threadPool[i])
    end
end

function ActivityDirectDrawMemberDialog:RefreshMemberGroup()
    local count = table.count(self.homeDojo.poolInfo.preview)
    if self._threadPool then
        self:ClearThreads()
    end
    self._threadPool = {}
    for i, item in ipairs(self.homeDojo.poolInfo.preview) do
        local itemId = item.rewards[1].goodsId
        local itemCount = item.rewards[1].num
        local itemType = GoodsUtils.GetIdType(itemId)
        local co = cs_coroutine.start(function()
            local go = CfUtils.InstantiateGo(self.GoodsAndHeadCell, self.Content)
            go.name = "Cell" .. checkString(i)
            CfUtils.FillText(go.transform:Find("Probability/TextNumber"), string.format("%2.4f", item.rate) .. "%")

            local isCard = true
            if itemType == Constants.IDType.CharacterCard then
                ---@type CardHeadNode
                local scr = CfUtils.GetLuaScr(go.transform:Find("CommonSmallHeadNode"), "Game.Behaviours.CardHeadNode")
                scr:FreshNodeByCardVo(itemId)
                scr:SetCallBack(function()
                    
                end)
            else
                isCard = false
                ---@type GoodNodeMB
                local scr = CfUtils.GetLuaScr(go.transform:Find("GoodNode"), "Game.Behaviours.GoodNodeMB")
                scr:Reload({
                    goodsId = itemId,
                    text = string.format("x%d", itemCount)
                })
                scr:SetClickButtonAction(function(goodsId)
                    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
                    GameUtils.ShowCommonTipsBoard(go, vo.name, vo.desc, vo.quality, vo.id, true)
                end)
            end

            CfUtils.SetActive(go.transform:Find("CommonSmallHeadNode"), isCard)
            CfUtils.SetActive(go.transform:Find("GoodNode"), not isCard)
            CfUtils.SetActive(go, true)
        end)
        table.insert(self._threadPool, co)
    end

end

function ActivityDirectDrawMemberDialog:RefreshEnsurance()
    CfUtils.FillText(self.EnsuranceMainText, checkString(self.homeDojo.poolInfo.poolDes))
end
